function render({ text, parameters, stepIndex, stepTime, random }) {
  const states = [text, parameters.textB, parameters.textC].map(value => parameters.uppercase ? value.toUpperCase() : value);
  const step = Math.max(0, Math.floor(stepIndex));
  if (step === 0) return states[0];
  if (step >= states.length) return states[states.length - 1];
  const from = Array.from(states[step - 1]);
  const to = Array.from(states[step]);
  const q = Math.max(0, Math.min(1, stepTime / Math.max(0.05, parameters.transitionDuration)));
  if (q >= 1) return states[step];
  const glyphs = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789#$%&*+-?";
  const count = Math.max(from.length, to.length);
  const frame = Math.floor(stepTime * 24);
  let result = "";
  for (let i = 0; i < count; i++) {
    const revealAt = 0.25 + random(step * 1009 + i * 17) * 0.7;
    if (q >= revealAt) result += to[i] || "";
    else if (q === 0) result += from[i] || "";
    else result += glyphs[Math.floor(random(step * 65537 + frame * 257 + i) * glyphs.length)];
  }
  return result;
}
